import { utf8Encode, writeUint32BE, xorInto } from '../utils/bytes.mjs';

export const DEFAULT_ITERATIONS = 1000;

export function pbkdf2Sha1(passwordBytes, saltBytes, iterations, keyLength) {
  if (!Number.isInteger(iterations) || iterations < 1) {
    throw new RangeError('iterations must be a positive integer');
  }

  if (!Number.isInteger(keyLength) || keyLength < 0) {
    throw new RangeError('keyLength must be a non-negative integer');
  }

  const derivedKey = new Uint8Array(keyLength);
  let offset = 0;
  let blockIndex = 1;

  while (offset < keyLength) {
    const blockInput = new Uint8Array(saltBytes.length + 4);
    blockInput.set(saltBytes);
    writeUint32BE(blockInput, saltBytes.length, blockIndex);

    let block = hmacSha1(passwordBytes, blockInput);
    const accumulator = block.slice();

    for (let iteration = 1; iteration < iterations; iteration += 1) {
      block = hmacSha1(passwordBytes, block);
      xorInto(accumulator, block);
    }

    const chunkLength = Math.min(accumulator.length, keyLength - offset);
    derivedKey.set(accumulator.subarray(0, chunkLength), offset);
    offset += chunkLength;
    blockIndex += 1;
  }

  return derivedKey;
}

export function deriveKey(passphrase, salt, keyLength = 16) {
  return pbkdf2Sha1(
    utf8Encode(passphrase),
    utf8Encode(salt),
    DEFAULT_ITERATIONS,
    keyLength,
  );
}

